Translate("deDE", "azshara", {
	title = "Azshara",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azshara ist ein Land roter Herbstwälder, zerbrochener Klippen und versunkener Ruinen an der Nordostküste von {link:kalimdor}Kalimdor{/link}, östlich von {link:ashenvale}Eschental{/link} und südlich von {link:winterspring}Winterspring{/link}. Es trägt den Namen von {link:queen-azshara}Königin Azshara{/link} und trägt die Erinnerung an sie wie eine Wunde. Zerschmetterte Tempel neigen sich über die Bucht der Stürme, die Säulen alter Städte liegen halb versunken in der Brandung, und die Geister der {link:high-elves}Hochgeborenen{/link} treiben noch immer zwischen den Steinen umher. Nur wenige kommen freiwillig hierher. Wer es tut, kommt wegen dessen, was die Ruinen noch verbergen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die Hochgeborenen zuerst an diesen Küsten bauten. Bekannt ist, dass dies im Zeitalter vor der {link:great-sundering}Großen Teilung{/link} ein Land ihrer Städte und Tempel war und dass ihre größten Magier die Gesetze des Arkanen auf Tafeln und Runen niederschrieben, damit alle sie lesen konnten. Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} am Ende des {link:war-of-the-ancients}Kriegs der Ahnen{/link} zerstört wurde, wurde das Land auseinandergerissen. Ein großer Teil der Stadt {link:ruins-of-eldarath}Eldarath{/link} stürzte ins Meer, und die Küste wurde zu dem zerklüfteten Gebilde, das sie heute ist. Die Königin und ihre Diener gingen unter den Wellen verloren. Die {link:night-elves}Nachtelfen{/link}, die überlebten, kehrten diesem Ort den Rücken, und seit zehntausend Jahren meiden sie ihn.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Azshara gehört niemandem, und jeder will etwas von ihm. Die {link:naga}Naga{/link} der Spitelash sind aus dem Meer zurückgekehrt, um die Ruinen ihrer Vorfahren zu beanspruchen. {link:satyrs}Satyrn{/link} der {link:haldarr-encampment}Haldarr{/link} und der {link:legashi-encampment}Legashi{/link} suchen die Wälder heim. Eine Schar Blutelfen unter der Magierin {link:magus-rimtori}Rimtori{/link} hat auf den nördlichen Steilhängen ihr Lager aufgeschlagen, um nach Schätzen der Hochgeborenen zu graben. Die {link:horde}Horde{/link} hält einen kleinen, blutgezeichneten Außenposten in {link:valormok}Valormok{/link}, und die {link:sentinels}Schildwachen{/link} halten von der {link:talrendis-point}Talrendisspitze{/link} an der Grenze zu {link:ashenvale}Eschental{/link} Wache. Ein menschlicher Erzmagier unterhält einen Turm in den westlichen Hügeln, ein Dämonenjäger lebt auf einer Insel in der Bucht, und ein blauer Drache bewacht die südlichen Wälder. Im Norden, hinter einem großen Tor, das kein Fremder je durchschritten hat, kämpfen {link:furbolgs}Furbolgs{/link} gegen eine Verderbnis, die aus der Tiefe aufsteigt.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:naga}Naga{/link} der Spitelash.{/b} Sie halten die Ruinen von {link:ruins-of-eldarath}Eldarath{/link}, die Strände und die Riffe, und ihr Kriegsherr herrscht vom {link:temple-of-zin-malor}Tempel von Zin-Malor{/link} aus.
• {b}Die {link:satyrs}Satyrn{/link}.{/b} Der Clan der {link:haldarr-encampment}Haldarr{/link} lauert nahe {link:valormok}Valormok{/link}, und die {link:legashi-encampment}Legashi{/link} halten die nördlichen Wälder.
• {b}Die Blutelfen.{/b} Landvermesser und Rückgewinner dienen {link:magus-rimtori}Magus Rimtori{/link}, die nach den Relikten der Hochgeborenen jagt.
• {b}Die {link:furbolgs}Furbolgs{/link} des Nordens.{/b} Sie bewachen das Tor von {link:blackmaw-hold}Blackmaw Hold{/link} und lassen keinen Fremden in seine Nähe.
• {b}Die Klippenriesen.{/b} Sie durchstreifen die südlichen Hügel und fressen den Stein des Landes selbst.
• {b}Der blaue Drachenschwarm.{/b} {link:azuregos}Azuregos{/link} und die Drachenbrut wachen über die alte Magie der Küste.
• {b}Die Makrura.{/b} Das Krabbenvolk des Tempels von {link:temple-of-arkkoran}Arkkoran{/link} verehrt seinen Herrn, {link:lord-arkkoroc}Lord Arkkoroc{/link}.
• {b}Die ruhelosen Toten.{/b} Erscheinungen der Hochgeborenen suchen die westlichen Schreine heim, gebunden an das Arkane, das sie liebten.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Hochgeborenen.{/b} {link:ruins-of-eldarath}Eldarath{/link} blühte, und seine Magier widmeten ihr Leben dem Studium des {link:arcane-magic}Arkanen{/link}.
• {b}Die Teilung.{/b} Der Brunnen implodierte, das Land zerbrach, und das Meer verschlang halb Eldarath.
• {b}Das lange Schweigen.{/b} Zehntausend Jahre lang waren die Ruinen Geistern, Tieren und den Gezeiten überlassen.
• {b}Die Gegenwart.{/b} Die {link:naga}Naga{/link} sind aus der Tiefe zurückgekehrt. Schatzsucher aller Völker sind ihnen gefolgt.]=],
		},
		{
			title = "Kunde der Küste",
			text = [=[• Die Klippenriesen des Südens verschlingen Fels und Ruinen gleichermaßen. Was durch sie hindurchgeht, erhärtet zu Azsharit, einem Kristall, der zugleich geschmeidig und sehr fest ist.
• Die Blutelfen nennen einen Goblin, der einst für sie arbeitete, „{link:kim-jael}Kim'jael{/link}“. Er schwört, es bedeute „kleine Ratte“, und er hat es ihnen nicht verziehen.
• Die Tafeln von {link:ruins-of-eldarath}Eldarath{/link} sind nach vier Zauberern der Hochgeborenen benannt: Beth'{link:moon-priestess-amara}Amara{/link}, Jin'yael, Markri und Sael'hai.]=],
		},
	},
})

Translate("deDE", "talrendis-point", {
	title = "Talrendisspitze",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Talrendisspitze ist der Außenposten der {link:sentinels}Schildwachen{/link} im Westen Azsharas, nahe der Grenze zu {link:ashenvale}Eschental{/link}. Er ist klein und wachsam. Ein Hippogryphenmeister hält den einzigen Weg nach Hause durch die Lüfte offen, und die Bognerin Brinna {link:valanaar}Valanaar{/link} bessert die Bögen der Schildwachen aus. Die Schildwachen hier beobachten die {link:horde}Horde{/link} in {link:valormok}Valormok{/link}, die {link:satyrs}Satyrn{/link} in den Hügeln und die Geister der westlichen Schreine. Ein Diener der Erdenmutter, {link:loh-atu}Loh'atu{/link}, lagert unter ihnen und hat geschworen, den Elfen zu helfen, das Land sowohl von den Satyrn als auch von den toten Hochgeborenen zu reinigen.]=],
		},
	},
})

Translate("deDE", "valormok", {
	title = "Valormok",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Valormok ist das Lager der {link:horde}Horde{/link} im westlichen {link:azshara}Azshara{/link}, nördlich des Lagers der {link:haldarr-encampment}Haldarr{/link}. Es ist ein einsamer Posten mit einem Windreitermeister, einem Schmied und einem Koch. Einst zählte er ein Dutzend Krieger. Die meisten von ihnen folgten der Blutelfe {link:magus-rimtori}Rimtori{/link} auf Befehl von Belgrom Rockmaul aus {link:orgrimmar}Orgrimmar{/link} in die Wildnis, und sie erschlug sie. {link:ag-tor-bloodfist}Ag'tor Bloodfist{/link}, der geblieben ist, will Rache. {link:jediga}Jediga{/link}, die zur Strafe hierhergeschickt wurde, will Gewinn. Keiner von beiden erwartet Hilfe aus Orgrimmar. Seine Windreiter sind der einzige schnelle Weg der Horde aus Azshara hinaus.]=],
		},
	},
})

Translate("deDE", "ruins-of-eldarath", {
	title = "Die Ruinen von Eldarath",
	aliases = { "Eldarath" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eldarath war eine Stadt der Hochgeborenen auf den Klippen über der Bucht der Stürme. Als die Welt zerbrach, stürzte ein großer Teil davon ins Meer. Was heute steht, ist ein Labyrinth aus bleichem Stein und zerbrochenen Bögen, gehalten von den {link:naga}Naga{/link} der Spitelash. Vier große Tafeln stehen noch zwischen den Ruinen, jede nach einem Zauberer der Hochgeborenen benannt, und Gelehrte von {link:ironforge}Ironforge{/link} bis {link:undercity}Undercity{/link} wollen Abschriften davon. Die Gezeitentümpel an ihrem Ufer sind verdorben. Ein {link:tauren}Tauren{/link}, der aus einem trank, erkrankte, und die Apotheker der Verlassenen zeigten ein unheilvolles Interesse an dem Wasser.]=],
		},
	},
})

Translate("deDE", "temple-of-zin-malor", {
	title = "Tempel von Zin-Malor",
	aliases = { "Zin-Malor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Tempel von Zin-Malor steht im Herzen der Ruinen von {link:ruins-of-eldarath}Eldarath{/link}. Einst barg er einen Kristall, der große arkane Kräfte bändigen und befehligen konnte. Jene, die ihn stahlen, hatten Böses im Sinn, und der Kristall zerbrach. Seine {link:the-night-watch}Wächter{/link} wurden zu verfluchten Geistern, und die heiligen Schriften der Hochgeborenen blieben in den Hallen des Tempels dem Verfall überlassen. Heute hält der {link:naga}Naga{/link}-{link:warlord-krellian}Kriegsherr Krellian{/link} den Tempel als seinen Sitz, hinter einer Mauer aus Wachen, und sammelt jede Magie, die er finden kann. Die Naga bewachen ihn erbitterter als jeden anderen Teil der Ruinen.]=],
		},
	},
})

Translate("deDE", "bay-of-storms", {
	title = "Die Bucht der Stürme",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Bucht der Stürme ist ein weiter, grauer Golf, der sich in die Mitte Azsharas frisst. Ihre Wasser sind ruhelos, und ihre Inseln sind wenige. An ihrem Nordufer liegt Hetaeras Gelege, der Hort einer dreiköpfigen Bestie, die sich die Herrscherin dieser Meere nennt. Die Makrura von {link:temple-of-arkkoran}Arkkoran{/link} jagen in ihren östlichen Gewässern, und unter allem schwimmen die {link:naga}Naga{/link}. Auf einer kleinen Insel im Süden, bewacht von drei Teufelshunden, lebt der Dämonenjäger {link:loramus-thalipedes}Loramus Thalipedes{/link}.]=],
		},
	},
})

Translate("deDE", "temple-of-arkkoran", {
	title = "Der Tempel von Arkkoran",
	aliases = { "Arkkoran" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Tempel von Arkkoran steht am Rand des Wassers im Osten Azsharas. Er ist die Heimat der Makrura, des Krabbenvolks der Küste, und des gewaltigen Wesens, dem sie dienen: {link:lord-arkkoroc}Lord Arkkoroc{/link}, den selbst der Dämonenjäger {link:loramus-thalipedes}Loramus{/link} einen niederen Gott nennt. Seine Orakel, Klapperer und Zwicker bewachen den Zugang und greifen jeden Fremden an, den sie finden. Wer ihn lebend erreicht, kann mit ihm verhandeln, doch er setzt stets einen Preis, und der letzte Preis, den er nannte, wurde mit Blut bezahlt.]=],
		},
	},
})

Translate("deDE", "thalassian-base-camp", {
	title = "Thalassischer Stützpunkt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Auf den Steilhängen der nördlichen Halbinsel hat eine Schar Blutelfen ihr Lager aufgeschlagen. Ihre Landvermesser und Rückgewinner durchkämmen das Land nach den verlorenen Schätzen der Hochgeborenen, und sie zermahlen die Magie, die sie finden, zu einem glitzernden Staub. Ihre Anführerin ist {link:magus-rimtori}Magus Rimtori{/link}. Sie heuerte {link:orcs}Orcs{/link} und einen Goblin an, um ihr zu helfen, und wandte sich gegen beide. Nahe ihren eigenen Zelten steht ein Kreis arkaner Kristalle, angelegt nach dem Muster eines alten Beschwörungsbuches.]=],
		},
	},
})

Translate("deDE", "legashi-encampment", {
	title = "Lager der Legashi",
	aliases = { "Legashi", "Festung der Legashi" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die {link:satyrs}Satyrn{/link} der Legashi halten die Wälder des nördlichen {link:azshara}Azshara{/link}, östlich von Ursolan und nördlich des Lagers der Blutelfen. Ihre Höllenrufer und Schurken dienen Meister Feardred. Auf einem Hügel über ihnen unterhält ein störrischer Goblin namens {link:kim-jael}Kim'jael{/link} ein eigenes Lager und scheint sie nicht zu fürchten. Von allen Satyrn Azsharas sind die Legashi die zahlreichsten. Reisende sagen, dass sich unlängst in der Nähe eine Festung von ihnen erhoben hat, doch niemand kann sagen, was sie beherbergt.]=],
		},
	},
})

Translate("deDE", "haldarr-encampment", {
	title = "Lager der Haldarr",
	aliases = { "Haldarr" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lager der Haldarr liegt im Südwesten Azsharas, nahe dem Lager der {link:horde}Horde{/link} in {link:valormok}Valormok{/link}. Es ist der Unterschlupf des Clans der Haldarr unter den {link:satyrs}Satyrn{/link}: Betrüger, Teufelsverschworene und Rohlinge, die einst Elfen waren. Sie schänden die Wälder, durch die einst {link:cenarius}Cenarius{/link} wandelte. {link:loh-atu}Loh'atu{/link} von der {link:talrendis-point}Talrendisspitze{/link} hat der Erdenmutter geschworen, zu helfen, sie zu vertreiben, und er entlohnt jene, die lebend aus ihrem Lager zurückkehren.]=],
		},
	},
})

Translate("deDE", "shadowsong-shrine", {
	title = "Shadowsong-Schrein",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Shadowsong-Schrein ist eine Ruine im Westen Azsharas, nordöstlich der {link:talrendis-point}Talrendisspitze{/link}. Es spukt dort. Erscheinungen der Hochgeborenen und Lichlinge treiben zwischen seinen Steinen umher, noch immer hungrig nach der arkanen Magie, die sie verdarb. Die Geister plagen alle Völker gleichermaßen, und ein Hunger wie der ihre soll den Blick der {link:burning-legion}Brennenden Legion{/link} auf sich ziehen. Die {link:sentinels}Schildwachen{/link} haben darum gebeten, dass sie aus der Welt erlöst werden. In der Nähe wandert ein finsterer Geist, einer, der den Namen des Hauptmanns von {link:queen-azshara}Königin Azshara{/link} trägt.]=],
		},
	},
})

Translate("deDE", "ravencrest-monument", {
	title = "Ravencrest-Monument",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Auf den Klippen der Südspitze Azsharas, über dem offenen Meer, liegen die Überreste einer kolossalen Statue der alten Elfen. Nur ihre Beine stehen noch. Der Rest liegt zerbrochen um sie herum oder ist in die Wellen gestürzt. Sie trägt den Namen des Hauses Ravencrest, doch keine Chronik verzeichnet, wen sie ehrte oder wann sie errichtet wurde. Die {link:naga}Naga{/link} der Spitelash streifen nun zwischen den Trümmern umher. Man erreicht sie nur vom Land aus, über eine Brücke.]=],
		},
	},
})

Translate("deDE", "southridge-beach", {
	title = "Southridge-Strand",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Southridge-Strand liegt an der Südküste Azsharas, unterhalb der Wälder, in denen der blaue Drache {link:azuregos}Azuregos{/link} Wache hält. Hierher kam das Schiff {i}Horizon Scout{/i} unter {link:captain-vanessa-beltis}Kapitänin Vanessa Beltis{/link} auf der Suche nach einem sicheren Ankerplatz. Die Sonne war noch keine Stunde untergegangen, als die {link:naga}Naga{/link} über ihre Mannschaft herfielen. Die Überlebenden verschanzten sich in einem Tal über dem Strand, und dort warten sie noch immer, wissend, dass die Naga zurückkehren werden. Einige ihrer Passagiere kamen in eigenen Geschäften nach {link:azshara}Azshara{/link}.]=],
		},
	},
})

Translate("deDE", "blackmaw-hold", {
	title = "Blackmaw Hold",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Norden Azsharas steht ein großes Tor der {link:furbolgs}Furbolgs{/link}. Solange sich irgendjemand in {link:kalimdor}Kalimdor{/link} erinnern kann, ist es verschlossen gewesen, und seine Wachen haben jeden Fremden vertrieben, der sich näherte. Dahinter liegt Blackmaw Hold, eine gewaltige Furbolgstadt, tief in den Berg gehauen. Ihr Volk kämpft gegen eine Verderbnis, die sich in ihren Tiefen zu regen begonnen hat. Es heißt, ihre Tunnel reichten noch weiter hinab, an Orte, die älter sind als die Stadt selbst.]=],
		},
	},
})

Translate("deDE", "loramus-thalipedes", {
	title = "Loramus Thalipedes",
	subtitle = "Der Dämonenjäger von Azshara",
	found = "Eine kleine Insel im Süden der Bucht der Stürme",
	hint = [=[Durchsucht die Inseln der Bucht der Stürme nach dem, der Dämonen jagt.]=],
	allegiance = "Keinem außer seiner eigenen Jagd",
	aliases = { "Loramus" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Loramus Thalipedes ist ein Dämonenjäger, der allein auf einer Insel in der Bucht der Stürme lebt. Drei Teufelshunde bewachen ihn: Raytaf, Shahiar und Zaman. Für Unterbrechungen hat er keine Geduld. Doch er weiß mehr über die Fürsten der {link:burning-legion}Brennenden Legion{/link} in dieser Welt als jeder Gelehrte der Königreiche, und er hilft jedem, der töricht genug ist, sie zu jagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Loramus ist der Einzige, der weiß, wie man {link:razelikh-the-defiler}Razelikh{/link} den Entweiher verwunden kann. Er kennt die Geschichte von Lord Kazzaks Rückzug in die faulende Narbe, den Pakt, der Razelikhs drei Hauptleute bindet, und den Ritus, durch den sich der wahre Name des Entweihers erfahren lässt. Ohne ihn könnte der Krieg gegen den Dämonenfürsten der {link:blasted-lands}Verwüsteten Lande{/link} überhaupt nicht geführt werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er vollzieht ein Ritual der Erleuchtung, um zu erfahren, wie Razelikhs Schutzbann gebrochen werden kann.
• Er schickt Suchende zu {link:lord-arkkoroc}Lord Arkkoroc{/link}, um den wahren Namen des Dämons zu erkaufen.
• Er bereitet gehärtetes Azsharit für den Schmied {link:galvan-the-ancient}Galvan{/link} den Uralten vor, der es als Einziger schmieden kann.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik verzeichnet, wer Loramus war, bevor er seine Jagd aufnahm, wie lange er schon auf seiner Insel lebt oder wie er {link:galvan-the-ancient}Galvan{/link} kennenlernte.]=],
		},
	},
	chapters = {
		{
			title = "Die Geschichte des Entweihers",
			hint = "Setzt Euch und hört die Geschichte des Dämonenjägers an.",
			text = [=[Wer vom Gefallenen Helden der {link:horde}Horde{/link} geschickt wird, findet Loramus wenig gastfreundlich. Er erzählt seine Geschichte dennoch, und er mag es nicht, unterbrochen zu werden. Als die Legion besiegt war, wurde {link:lord-kazzak}Kazzak{/link} in die faulende Narbe zurückgedrängt, und {link:razelikh-the-defiler}Razelikh{/link}, der gefürchtetste seiner Leutnants, wurde ausgesandt, um das Land für ihn zu halten. Die {link:ogres}Oger{/link} und die Kultisten stellten sich an seine Seite, ebenso die drei, die nun sein Amulett bewachen.]=],
		},
		{
			title = "Der Name der Bestie",
			hint = "Erfahrt den wahren Namen des Dämons vom Herrn der Makrura.",
			text = [=[Nur eine Waffe, die den wahren Namen eines Dämons trägt, kann ihm und allen, die ihm dienen, schaden. Loramus konnte diesen Namen nicht selbst erfahren. Er schickte seinen Helfer zum Tempel von {link:temple-of-arkkoran}Arkkoran{/link}, und der Preis des Herrn der Makrura war Blut. Der Name kam zurück, zusammen mit einer Härtung, die aus den Köpfen einer Bestie gewonnen wurde: {link:razelikh-the-defiler}Rakh'likh{/link}.]=],
		},
		{
			title = "Felbane",
			hint = [=[Bringt die Lieferung des Dämonenjägers zum Schmied des Mithrilordens.]=],
			text = [=[Mit Azsharit aus den südlichen Hügeln und der Härtung Arkkorocs waren die Materialien bereit. Loramus sandte sie nach Süden zu {link:galvan-the-ancient}Galvan{/link} dem Uralten im {link:stranglethorn-vale}Schlingendorntal{/link}. Der alte Schmied hatte den Namen des Dämonenjägers seit vielen Jahren nicht mehr gehört.]=],
		},
	},
	mentions = {
		{ text = "Der Dämonenjäger" },
		{ text = "Loramus" },
		{ text = "Den Schutzbann brechen" },
		{ text = "Der Name der Bestie" },
		{ text = "Azsharit" },
		{ text = "Die Schmiedung von Felbane" },
	},
	bonds = {
		{ id = "razelikh-the-defiler", name = "Razelikh der Entweiher", note = "der Dämon, den er jagt" },
		{ id = "lord-kazzak", name = "Lord Kazzak", note = "der Herr des Entweihers" },
		{ id = "lord-arkkoroc", name = "Lord Arkkoroc", note = "kennt den wahren Namen" },
		{ id = "galvan-the-ancient", name = "Galvan der Uralte", note = "ein alter Bekannter" },
		{ id = "fallen-hero-of-the-horde", name = "Gefallener Held der Horde", note = "schickt ihm Jäger" },
	},
})

Translate("deDE", "archmage-xylem", {
	title = "Erzmagier Xylem",
	subtitle = "Herr des Turms in den Hügeln",
	found = "Sein Turm auf den Klippen über dem westlichen Azshara",
	hint = [=[Findet den Erzmagier, dessen Turm über Azshara wacht. Sein Diener wartet unten.]=],
	allegiance = "Seine eigenen Studien",
	aliases = { "Xylem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzmagier Xylem ist ein menschlicher Magier, der sein Heim in einem Turm hoch in den Hügeln über {link:azshara}Azshara{/link} errichtet hat. Besucher müssen zuerst seinen Diener {link:sanath-lim-yo}Sanath Lim-yo{/link} finden, der sie mit Magie hinauf in den Turm schickt. Xylem ist stolz, kalt und sehr mächtig. Er ist ein Mensch, wie {link:jediga}Jediga{/link} aus {link:valormok}Valormok{/link} sagt, doch er benimmt sich wie kein Mensch, dem sie je begegnet ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Xylem kam aus demselben Grund nach {link:azshara}Azshara{/link} wie alle anderen: wegen seiner Magie. Er kauft das Wissen der Hochgeborenen, erntet die verzauberte Koralle der Bucht und beobachtet das Land durch Wahrsagezauber. Selbst der Schurkenfürst {link:lord-jorach-ravenholdt}Jorach Ravenholdt{/link} wendet sich an ihn, wenn eine Verzauberung gebrochen werden muss.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bezahlt {link:jediga}Jediga{/link} für die Tafel von Sael'hai aus den Ruinen von {link:ruins-of-eldarath}Eldarath{/link}.
• Er schickte einen Lehrling, um mit den Blutelfen um ihren glitzernden Staub zu handeln, und die Blutelfen töteten den Lehrling.
• Er arbeitet daran, die Verzauberung eines versiegelten azurblauen Beutels für Lord {link:ravenholdt-manor}Ravenholdt{/link} zu brechen.
• Er schickt einen Jäger hinter {link:warlord-krellian}Kriegsherr Krellian{/link} und der prismatischen Muschel her, die der {link:naga}Naga{/link} begehrt.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik verzeichnet, woher Xylem kam, warum er {link:azshara}Azshara{/link} wählte oder was er mit allem vorhat, was er sammelt.]=],
		},
	},
	chapters = {
		{
			title = "Die Tafel von Sael'hai",
			hint = "Liefert die letzte von Jedigas Tafeln an den Erzmagier.",
			text = [=[{link:jediga}Jediga{/link} warnte, Xylem sei der gefährlichste all ihrer Käufer. Er nahm die Tafel und zahlte genau so, wie er es versprochen hatte. Das überraschte sie mehr, als jeder Verrat es getan hätte.]=],
		},
		{
			title = "Die alte Nemesis",
			hint = "Rächt den Lehrling des Erzmagiers im versunkenen Tempel.",
			text = [=[Vor Jahren überfiel der grüne Drache {link:morphaz}Morphaz{/link} Xylem aus dem Hinterhalt und verschlang einen seiner Lehrlinge im Ganzen. Xylem trauerte nicht um den Lehrling. Er trauerte um den arkanen Splitter, den der Lehrling bei sich trug. Als der Splitter im {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link} aus dem Bauch des Drachen geschnitten wurde, war er mit der Macht des Drachen gewachsen. Mit ihm war die volle Kunst des Erzmagiers wiederhergestellt.]=],
		},
	},
	mentions = {
		{ text = "Lieferung an Erzmagier Xylem" },
		{ text = "Xylems Bezahlung an {link:jediga}Jediga{/link}" },
		{ text = "Verschlüsselte Fragmente" },
		{ text = "Der azurblaue Schlüssel" },
		{ text = "Magischer Staub" },
		{ text = "Die Koralle der Sirene" },
		{ text = "Vernichtet {link:morphaz}Morphaz{/link}" },
		{ text = "{link:warlord-krellian}Kriegsherr Krellian{/link}" },
		{ text = "Bruchstückhafte Magie" },
	},
	bonds = {
		{ id = "sanath-lim-yo", name = "Sanath Lim-yo", note = "sein Diener" },
		{ id = "jediga", name = "Jediga", note = "verkaufte ihm eine Tafel" },
		{ id = "lord-jorach-ravenholdt", name = "Lord Jorach Ravenholdt", note = "bat ihn um einen Gefallen" },
		{ id = "morphaz", name = "Morphaz", note = "seine alte Nemesis" },
		{ id = "warlord-krellian", name = "Kriegsherr Krellian", note = "hält die Muschel, die er will" },
		{ id = "magus-rimtori", name = "Magus Rimtori", note = "ihr Volk erschlug seinen Lehrling" },
	},
})

