	},
})

Translate("deDE", "jediga", {
	title = "Jediga",
	subtitle = "Reliktenhändlerin in Valormok",
	found = "Valormok",
	hint = [=[Sprecht mit der Frau in Valormok, die ihr Exil zu einem Handel gemacht hat.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jediga wurde von Belgrom Rockmaul zur Strafe nach {link:azshara}Azshara{/link} geschickt. Sie hat das Beste daraus gemacht. Bevor sie kam, erfuhr sie, wie viel Wertvolles zwischen den Ruinen liegt und wer dafür bezahlen könnte. Nun handelt sie mit den Tafeln der Hochgeborenen, und ihre Käufer gehören zu den seltsamsten Leuten Kalimdors.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jedigas Handel zeigt, wie viele Augen auf {link:azshara}Azshara{/link} gerichtet sind. Ihre Tafeln gehen an eine Älteste der Grimmtotem, einen Gelehrten namens Jes'rimon, Andron Gant und einen menschlichen Erzmagier.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sucht die vier Tafeln der Ruinen von {link:ruins-of-eldarath}Eldarath{/link}.
• Sie verkauft je eine an {link:magatha-grimtotem}Magatha Grimtotem{/link}, Jes'rimon, Andron Gant und {link:archmage-xylem}Erzmagier Xylem{/link}.
• Sie bezahlt ihre Helfer erst nach dem Nachweis der Lieferung.]=],
		},
	},
	mentions = {
		{ text = "Wissen stehlen" },
		{ text = "Lieferung an {link:magatha-grimtotem}Magatha{/link}" },
		{ text = "Lieferung an Jes'rimon" },
		{ text = "Lieferung an Andron Gant" },
		{ text = "Lieferung an {link:archmage-xylem}Erzmagier Xylem{/link}" },
	},
	bonds = {
		{ id = "archmage-xylem", name = "Erzmagier Xylem", note = "der Käufer, dem sie am wenigsten traut" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "eine Käuferin" },
		{ id = "ag-tor-bloodfist", name = "Ag'tor Bloodfist", note = "teilt ihr Exil" },
	},
})

Translate("deDE", "ag-tor-bloodfist", {
	title = "Ag'tor Bloodfist",
	subtitle = "Krieger von Valormok",
	found = "Valormok",
	hint = [=[Sprecht mit dem letzten Krieger von Valormok, der Rache will.]=],
	allegiance = "Horde",
	aliases = { "Ag'tor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ag'tor Bloodfist ist einer der wenigen {link:orcs}Orcs{/link}, die in {link:valormok}Valormok{/link} geblieben sind. Die Blutelfe {link:magus-rimtori}Rimtori{/link} versprach Belgrom Rockmaul große Reichtümer, wenn er ihr seine Krieger lieh. Sie führte sie in die Wildnis und tötete sie alle. Ag'tor blieb, weil er sie bestraft sehen wollte, und weil er halb versteht, warum Belgrom getäuscht wurde.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ag'tor ist der Groll der {link:horde}Horde{/link} in {link:azshara}Azshara{/link}. Er kann keine weiteren Krieger schicken, denn es sind keine mehr übrig.]=],
		},
		{
			title = "Taten",
			text = [=[• Er greift die Rückgewinner und Landvermesser der Blutelfen auf der nördlichen Halbinsel an.
• Er verlangt den Kopf von {link:magus-rimtori}Magus Rimtori{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Verraten",
			hint = "Rächt die Krieger von Valormok.",
			text = [=[Rimtoris Buch zeigte das Muster ihres Kreises. Ein Kristall war an sie gebunden. Die anderen waren an etwas weit Schlimmeres gebunden. Als ihr Kristall zerbrach, kam sie, und sie starb. Ag'tor brüllte vor Freude und schickte ihren Kopf zu Belgrom.]=],
		},
	},
	mentions = {
		{ text = "Verraten" },
		{ text = "Verraten" },
		{ text = "Verraten" },
	},
	bonds = {
		{ id = "magus-rimtori", name = "Magus Rimtori", note = "seine Feindin" },
		{ id = "jediga", name = "Jediga", note = "teilt seinen Posten" },
	},
})

Translate("deDE", "magus-rimtori", {
	title = "Magus Rimtori",
	subtitle = "Schatzsucherin der Blutelfen",
	found = "Ihr Lager auf den Steilhängen der nördlichen Halbinsel",
	hint = [=[Findet das Lager der Magierin, die Valormok verriet. Etwas dort wird sie hervorlocken.]=],
