	aliases = { "Rimtori" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magus Rimtori ist eine Blutelfenmagierin, die die Schatzsucher Azsharas anführt. Sie ist klug, und ihr Charme ist eine Waffe. Sie versprach Belgrom Rockmaul Reichtümer für die Leihgabe seiner Krieger und erschlug sie dann. Sie heuerte den Goblin {link:kim-jael}Kim'jael{/link} an und versuchte dann, ihn zu töten. Sie durchstreift mit ihren Leibwächtern das Land, auf der Suche.]=],
