		{
			title = "Taten",
			text = [=[• Sie verriet die Hordenkrieger von {link:valormok}Valormok{/link}.
• Sie sucht eine Rune, die die {link:naga}Naga{/link} von {link:ruins-of-eldarath}Eldarath{/link} besitzen.
• Sie errichtete in ihrem Lager einen Kreis arkaner Kristalle.]=],
		},
	},
	mentions = {
		{ text = "Verraten" },
