	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kim'jael ist ein Goblinhändler, der das Gold der Blutelfen nahm, um ihnen bei der Schatzsuche zu helfen. Als sie keine Verwendung mehr für ihn hatten, versuchten sie, ihn zu töten, und behielten seine Ausrüstung. Sie gaben ihm auch den Namen, den er jetzt trägt und der, wie er sagt, „kleine Ratte“ bedeutet. Er will seine Ausrüstung zurück, und er will wissen, wonach sie suchten.]=],
