			title = "Taten",
			text = [=[• Er will seinen Kompass, sein Fernrohr, sein ausgestopftes Huhn und ein Gerät zurück, das er einen Wizzlegoober nennt.
• Er sucht die Rune, die die Blutelfen von den {link:naga}Naga{/link} von {link:ruins-of-eldarath}Eldarath{/link} wollten.]=],
		},
	},
	mentions = {
		{ text = "Kim'jael, in der Tat!" },
		{ text = "Kim'jaels „verschwundene“ Ausrüstung" },
	},
	bonds = {
		{ id = "magus-rimtori", name = "Magus Rimtori", note = "heuerte ihn an und verriet ihn" },
	},
})

Translate("deDE", "loh-atu", {
