Translate("deDE", "duke-hydraxis", {
	title = "Herzog Hydraxis",
	subtitle = "Herr der Hydraxianer",
	found = "Eine Insel vor der Ostküste Azsharas",
	hint = [=[Sucht den Herrn des Wassers auf einer Insel vor Azsharas Ostküste.]=],
	allegiance = "Hydraxianer",
	aliases = { "Hydraxis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Herzog Hydraxis ist ein Elementarfürst des Wassers, der auf einer Insel vor der Ostküste Azsharas wohnt. Er befehligt die Hydraxianer. Er trägt einen Aspekt Neptulons in sich, des großen Herrn der Gezeiten, und er führt einen alten Krieg gegen die niederen {link:elements}Elemente{/link}: Luft, Erde und vor allem Feuer.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hydraxis ist eine der wenigen elementaren Mächte, die mit Sterblichen verhandeln. Er tut es für seinen Krieg. {link:alliance}Allianz{/link} und {link:horde}Horde{/link} sind ihm gleichgültig; ihm geht es nur um die Reinheit des Wassers und um die Niederlage des Feuers. In Sterblichen, die bereit sind zu kämpfen, sieht er die Möglichkeit eines wahren Bündnisses.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht die Elementare des Wassers zu heilen, die die Seuche Lordaerons verzerrt hat.
• Er schickt seine Verbündeten gegen die Diener von Luft und Erde im {link:the-crystal-vale}Kristalltal{/link} von {link:silithus}Silithus{/link}.
• Er strebt die Niederlage der Diener des Feuers an, die den {link:blackrock-mountain}Blackrock{/link} halten.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik der Sterblichen verzeichnet, wie lange Hydraxis seine Insel schon hält oder warum die Hydraxianer {link:azshara}Azshara{/link} wählten.]=],
		},
	},
	chapters = {
		{
			title = "Vergiftetes Wasser",
			hint = [=[Helft den Hydraxianern, ihre verderbten Artgenossen wiederherzustellen.]=],
			text = [=[Eine Schar von Wasserelementaren zog in die Östlichen Pestländer und kehrte krank zurück. Für die Hydraxianer war so etwas ein Frevel. Hydraxis gab eine Phiole mit Neptulons eigener Essenz, um sie zu heilen. Das Heilmittel konnte den Wahnsinn, der folgte, nicht besänftigen.]=],
		},
		{
			title = "Das Auge des Glutsehers",
			hint = [=[Beweist Eure Stärke gegen einen gefangenen Diener des Feuers.]=],
			text = [=[Hoch oben in der Blackrockspitze hatten die {link:orcs}Orcs{/link} einen Diener des Feuers angekettet. Hydraxis wollte sein Auge. Als es zu ihm kam, befand er, dass sein neuer Verbündeter sowohl List als auch Stärke besaß, und er begann, vom Geschmolzenen Kern zu sprechen.]=],
		},
	},
	mentions = {
		{ text = "Vergiftetes Wasser" },
		{ text = "Stürmer und Rumpler" },
		{ text = "Das Auge des Glutsehers" },
		{ text = "Der Geschmolzene Kern" },
		{ text = "Agent von Hydraxis" },
		{ text = "Hände des Feindes" },
	},
	bonds = {
		{ id = "ragnaros", name = "Ragnaros", note = "sein Feind" },
	},
})

Translate("deDE", "azuregos", {
	title = "Azuregos",
	subtitle = "Wächter der arkanen Küsten",
	found = "Die südlichen Wälder Azsharas",
	hint = [=[Sucht den großen blauen Drachen in den südlichen Wäldern. Geht nicht allein.]=],
	allegiance = "Blauer Drachenschwarm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azuregos ist ein großer blauer Drache, der über das südliche {link:azshara}Azshara{/link} wacht. Die Küsten hier sind reich an alter Magie, und die Ruinen bergen noch die Relikte der Hochgeborenen. Azuregos ist hier, um sie von sterblichen Händen fernzuhalten. Er verbirgt nicht, was er ist. Er warnt Eindringlinge, sich zu entfernen, und dann kämpft er gegen sie.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der blaue Drachenschwarm hat die Magie der Welt stets vor jenen bewahrt, die sie missbrauchen würden. Dass ein so mächtiger Drache wie Azuregos seinen Posten in {link:azshara}Azshara{/link} hält, sagt viel darüber aus, was hier verborgen liegen mag. Manche flüstern, dass selbst die sagenhaften Phiolen der Ewigkeit in diesen Wäldern gefunden worden sein könnten.

Die Schatzsucher, die sich in Azshara drängen, Blutelfen, {link:naga}Naga{/link}, Goblins und Erzmagier gleichermaßen, kommen alle wegen derselben Magie, die er bewacht. Früher oder später muss sich jeder von ihnen mit dem Drachen auseinandersetzen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bewacht die magischen Schätze Azsharas gegen jeden, der kommt.
• Er erforscht die magiereichen Ufer der Küste und sucht, was immer die Teilung zurückließ.
• Blaue Drachenbrut, Magierfürsten und Magieweber seines Schwarms halten unter seinem Blick Wache über das Land.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik verzeichnet, wann Azuregos nach {link:azshara}Azshara{/link} kam oder was genau er bewacht. Es heißt, die blauen Drachen hätten seit vielen Generationen über die Ruinen von {link:ruins-of-eldarath}Eldarath{/link} gewacht, doch ob Azuregos von Anfang an unter ihnen war, kann niemand sagen.]=],
		},
	},
	bonds = {
		{ id = "queen-azshara", name = "Königin Azshara", note = "die Königin, deren Relikte er bewacht" },
	},
})

